     9|const SCHEMA = "vita_hero";
    10|const NEON_AUTH = "https://ep-super-tree-afp87aw4.neonauth.c-2.us-west-2.aws.neon.tech/neondb/auth";
    11|const TWILIO_API = "https://api.twilio.com/2010-04-01";
    12|const OTP_EXPIRY_MINUTES = 5;
    13|const OTP_MAX_ATTEMPTS = 5;
    14|
    15|interface Env {
    16|  DATABASE_URL: string;
    17|  TWILIO_ACCOUNT_SID: string;
    18|  TWILIO_AUTH_TOKEN: string;
    19|}
