    21|// ─── Helpers ────────────────────────────────────────────────
    22|
    23|function cors(response: Response): Response {
    24|  const headers = new Headers(response.headers);
    25|  headers.set("Access-Control-Allow-Origin", "*");
    26|  headers.set("Access-Control-Allow-Methods", "GET,POST,PUT,PATCH,DELETE,OPTIONS");
    27|  headers.set("Access-Control-Allow-Headers", "Content-Type,Authorization");
    28|  headers.set("Access-Control-Max-Age", "86400");
    29|  return new Response(response.body, { status: response.status, headers });
    30|}
    31|
    32|function json(data: unknown, status = 200): Response {
    33|  return cors(new Response(JSON.stringify(data), {
    34|    status,
    35|    headers: { "Content-Type": "application/json" },
    36|  }));
    37|}
    38|
    39|function extractToken(request: Request): string {
    40|  return (request.headers.get("Authorization") || "").replace("Bearer ", "");
    41|}
    42|
    43|function generateToken(): string {
    44|  return crypto.randomUUID().replace(/-/g, "") + crypto.randomUUID().replace(/-/g, "").slice(0, 16);
    45|}
    46|
    47|function generateOtp(): string {
    48|  return String(Math.floor(100000 + Math.random() * 900000));
    49|}
