    70|// ─── Twilio SMS ─────────────────────────────────────────────
    71|
    72|async function sendTwilioSms(
    73|  env: Env,
    74|  to: string,
    75|  body: string
    76|): Promise<boolean> {
    77|  const sid = env.TWILIO_ACCOUNT_SID;
    78|  const token = env.TWILIO_AUTH_TOKEN;
    79|  if (!sid || !token) {
    80|    console.error("Twilio credentials not configured");
    81|    return false;
    82|  }
    83|  try {
    84|    const resp = await fetch(
    85|      `${TWILIO_API}/Accounts/${sid}/Messages.json`,
    86|      {
    87|        method: "POST",
    88|        headers: {
    89|          Authorization: "Basic " + btoa(`${sid}:${token}`),
    90|          "Content-Type": "application/x-www-form-urlencoded",
    91|        },
    92|        body: new URLSearchParams({
    93|          To: to,
    94|          From: "+12562828337", // Will be overridden by Twilio trial/project number
    95|          Body: body,
    96|        }),
    97|      }
    98|    );
    99|    return resp.ok;
   100|  } catch (e) {
   101|    console.error("Twilio send error:", e);
   102|    return false;
   103|  }
