   144|/** Create or update a profile in vita_hero.profiles after Neon Auth success. */
   145|async function upsertProfileFromNeonAuth(
   146|  sql: ReturnType<typeof neon>,
   147|  user: NeonAuthUser,
   148|  provider: string
   149|): Promise<{ profileId: string; sessionToken: string }> {
   150|  const profileId = `na_${user.id.slice(0, 24)}`;
   151|  const sessionToken = generateToken();
   152|
   153|  const existing = await sql`
   154|    SELECT id FROM ${sql(SCHEMA)}.profiles WHERE id = ${profileId} LIMIT 1
   155|  `;
   156|
   157|  if (existing.length === 0) {
   158|    await sql`
   159|      INSERT INTO ${sql(SCHEMA)}.profiles
   160|        (id, user_id, name, email, session_token, auth_provider,
   161|         onboarding_complete, is_logged_in)
   162|      VALUES (
   163|        ${profileId}, ${user.id}, ${user.name || user.email.split('@')[0]},
   164|        ${user.email}, ${sessionToken}, ${provider}, true, true
   165|      )
   166|    `;
   167|  } else {
   168|    await sql`
   169|      UPDATE ${sql(SCHEMA)}.profiles
   170|      SET session_token = ${sessionToken}, is_logged_in = true,
   171|          name = ${user.name || user.email.split('@')[0]},
   172|          email = ${user.email}, auth_provider = ${provider}
   173|      WHERE id = ${profileId}
   174|    `;
   175|  }
   176|
   177|  return { profileId, sessionToken };
   178|}
