   544|      // ═══════════════════════════════════════════════════
   545|      // Kids
   546|      // ═══════════════════════════════════════════════════
   547|
   548|      if (path === "/api/kids" && request.method === "GET") {
   549|        if (!session) return json({ error: "Unauthorized" }, 401);
   550|        const profileId = session.profileId;
